{
  "requirement_id": "REQ-004",
  "cases": [
    {
      "id": "TC-1",
      "title": "Create task via form updates list immediately without page reload",
      "surface": "ui",
      "steps": [
        "Open GET /?user=alice&project=1",
        "Wait for body[data-ready='true']",
        "Type 'Test Task' into input[data-testid='new-title']",
        "Click button[data-testid='create-btn']"
      ],
      "expected": "透過表單建立任務成功後，列表須立即顯示新任務，不需重新整理頁面。"
    },
    {
      "id": "TC-2",
      "title": "Task title with HTML tags is rendered as literal text",
      "surface": "ui",
      "steps": [
        "Open GET /?user=alice&project=1",
        "Wait for body[data-ready='true']",
        "Type '<b>Bold Title</b>' into input[data-testid='new-title']",
        "Click button[data-testid='create-btn']"
      ],
      "expected": "任務標題須以純文字顯示：標題若含 HTML 標記（例如 <b>x</b>），畫面上應顯示字面文字，不得被解析成元素。"
    },
    {
      "id": "TC-3",
      "title": "API error displays message in the error area",
      "surface": "ui",
      "steps": [
        "Open GET /?user=alice&project=99999",
        "Wait for body[data-ready='true']"
      ],
      "expected": "API 錯誤時於錯誤區顯示訊息。"
    }
  ]
}

